using System.Text;
using BinaryParser;
using TableAutomationTool.Common.Utils;
using TableAutomationTool.UserEnum;

namespace TableAutomationTool.Generator.CodeGenerator
{
    public struct CSharpInfoParam
    {
        /// <summary>테이블 코드(Template/Info/InfoManager/InfoHandler) 출력 폴더</summary>
        public string infoRootDirectory;
        /// <summary>DataManager 폴더. Base/DataManagerAutoGenerated.cs 를 여기에 쓴다. 비면 infoRootDirectory.</summary>
        public string managerRootDirectory;
        public string @namespace;
    }

    /// <summary>
    /// Binary 스키마로 Unity 클라이언트의 Info 구조를 생성한다.
    ///
    ///   {root}/{T}InfoTemplate.cs                  : 데이터 원본         (매번 재생성)
    ///   {root}/{T}Info.cs                          : 커스텀 로직         (최초 1회)
    ///   {root}/{T}InfoManager.cs                   : 테이블 로딩         (최초 1회)
    ///   {root}/{T}InfoHandler.cs                   : 조회 래퍼           (최초 1회)
    ///   {root}/Base/DataManagerAutoGenerated.cs    : InfoManager 등록부  (매번 재생성)
    ///
    /// {T} 는 .bin 이름(= 워크시트 이름), 키는 첫 번째 컬럼이다.
    /// 베이스 타입(InfoManagerBase, IInfoTemplate, InfoRow 등)은 {root}/Base 에 수작업으로 둔다.
    /// </summary>
    public class CSharpInfoGenerator
    {
        private const string BaseFolder = "Base";
        private const string DataManagerFileName = "DataManagerAutoGenerated.cs";

        private static readonly HashSet<string> CSharpKeywords = new(StringComparer.Ordinal)
        {
            "abstract", "as", "base", "bool", "break", "byte", "case", "catch", "char", "checked", "class", "const",
            "continue", "decimal", "default", "delegate", "do", "double", "else", "enum", "event", "explicit",
            "extern", "false", "finally", "fixed", "float", "for", "foreach", "goto", "if", "implicit", "in", "int",
            "interface", "internal", "is", "lock", "long", "namespace", "new", "null", "object", "operator", "out",
            "override", "params", "private", "protected", "public", "readonly", "ref", "return", "sbyte", "sealed",
            "short", "sizeof", "stackalloc", "static", "string", "struct", "switch", "this", "throw", "true", "try",
            "typeof", "uint", "ulong", "unchecked", "unsafe", "ushort", "using", "virtual", "void", "volatile", "while",
        };

        private readonly CSharpInfoParam _param;

        public CSharpInfoGenerator(CSharpInfoParam param)
        {
            _param = param;
        }

        /// <summary>
        /// 테이블 1개의 Template(재생성)과 Info/InfoManager/InfoHandler(없을 때만)를 만든다.
        /// </summary>
        public bool GenerateTable(string binaryFilePath)
        {
            if (!TryReadTable(binaryFilePath, out var table))
                return false;

            var root = _param.infoRootDirectory;
            Directory.CreateDirectory(root);
            WriteAlways(Path.Combine(root, $"{table.Name}InfoTemplate.cs"), BuildTemplate(table));
            WriteIfMissing(Path.Combine(root, $"{table.Name}Info.cs"), BuildInfo(table));
            WriteIfMissing(Path.Combine(root, $"{table.Name}InfoManager.cs"), BuildInfoManager(table));
            WriteIfMissing(Path.Combine(root, $"{table.Name}InfoHandler.cs"), BuildInfoHandler(table));
            return true;
        }

        /// <summary>
        /// 전체 테이블 목록으로 DataManagerAutoGenerated.cs 를 다시 만든다.
        /// -each 로 일부만 생성할 때도 등록부는 전체 목록 기준이어야 하므로 항상 모든 .bin 을 받는다.
        /// </summary>
        public void GenerateDataManager(IEnumerable<string> allBinaryFilePaths)
        {
            var tableNames = allBinaryFilePaths
                .Select(Path.GetFileNameWithoutExtension)
                .OfType<string>()
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(n => n, StringComparer.Ordinal)
                .ToList();

            var managerRoot = string.IsNullOrWhiteSpace(_param.managerRootDirectory)
                ? _param.infoRootDirectory
                : _param.managerRootDirectory;
            var directory = Path.Combine(managerRoot, BaseFolder);
            Directory.CreateDirectory(directory);
            WriteAlways(Path.Combine(directory, DataManagerFileName), BuildDataManager(tableNames));
        }

        /// <summary>
        /// 더 이상 .bin 이 없는 테이블의 Template 을 지운다. (전체 생성 시에만 호출)
        /// Info/InfoManager/InfoHandler 등 사용자 파일은 건드리지 않는다.
        /// </summary>
        public void RemoveStaleTemplates(IEnumerable<string> allBinaryFilePaths)
        {
            var root = _param.infoRootDirectory;
            if (!Directory.Exists(root))
                return;

            var expected = new HashSet<string>(
                allBinaryFilePaths.Select(p => $"{Path.GetFileNameWithoutExtension(p)}InfoTemplate.cs"),
                StringComparer.OrdinalIgnoreCase);

            foreach (var file in Directory.GetFiles(root, "*InfoTemplate.cs"))
            {
                if (expected.Contains(Path.GetFileName(file)))
                    continue;

                File.Delete(file);
                var meta = file + ".meta";
                if (File.Exists(meta))
                    File.Delete(meta);
                Logger.Instance.Log($"[CSharpInfoGenerator] Removed stale template: {file}");
            }
        }

        // ============================================================
        // Builders
        // ============================================================

        private string BuildTemplate(TableSchema table)
        {
            var sb = new StringBuilder();
            AppendAutoGeneratedHeader(sb, "매번 재생성됩니다. 수정하지 마세요. 커스텀 로직은 " + $"{table.Name}Info.cs 에 작성합니다.");
            foreach (var usingNamespace in CollectTemplateUsings(table))
                sb.AppendLine($"using {usingNamespace};");
            sb.AppendLine();
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {table.Name} 테이블 데이터 원본");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public class {table.Name}InfoTemplate : IInfoTemplate<{table.KeyType}>");
            sb.AppendLine("    {");

            foreach (var column in table.Columns)
                sb.AppendLine($"        public {column.Type} {column.Name} {{ get; private set; }}");
            sb.AppendLine();

            sb.AppendLine($"        protected {table.Name}InfoTemplate()");
            sb.AppendLine("        {");
            sb.AppendLine("        }");
            sb.AppendLine();

            sb.AppendLine($"        public {table.Name}InfoTemplate(");
            sb.AppendLine(string.Join(",\n", table.Columns.Select(c => $"            {c.Type} {c.ParameterName}")));
            sb.AppendLine("        )");
            sb.AppendLine("        {");
            foreach (var column in table.Columns)
                sb.AppendLine($"            {column.Name} = {column.ParameterName};");
            sb.AppendLine("        }");
            sb.AppendLine();

            sb.AppendLine($"        {table.KeyType} IInfoTemplate<{table.KeyType}>.InfoKey => {table.Columns[0].Name};");
            sb.AppendLine();

            sb.AppendLine($"        void IInfoTemplate<{table.KeyType}>.Deserialize(InfoRow row)");
            sb.AppendLine("        {");
            foreach (var column in table.Columns)
                sb.AppendLine($"            {column.Name} = row.Get<{column.Type}>(\"{column.Name}\");");
            sb.AppendLine("        }");

            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        /// <summary>
        /// Template 파일의 using 목록. System 과, 칼럼에 쓰인 enum 이 선언된 네임스페이스(EnumDB 기준)를 넣는다.
        /// </summary>
        private IEnumerable<string> CollectTemplateUsings(TableSchema table)
        {
            var enumNamespaces = new SortedSet<string>(StringComparer.Ordinal);
            foreach (var column in table.Columns)
            {
                var elementType = column.Type.EndsWith("[]") ? column.Type[..^2] : column.Type;
                var enumNamespace = EnumDB.Instance.GetEnumNamespace(elementType);
                if (!string.IsNullOrEmpty(enumNamespace) && enumNamespace != _param.@namespace && enumNamespace != "System")
                    enumNamespaces.Add(enumNamespace);
            }
            return enumNamespaces.Prepend("System");
        }

        private string BuildInfo(TableSchema table)
        {
            var sb = new StringBuilder();
            AppendOnceHeader(sb);
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {table.Name} 테이블 데이터. 프로젝트 전용 로직을 여기에 추가한다.");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public partial class {table.Name}Info : {table.Name}InfoTemplate, IInfoValidateChecker");
            sb.AppendLine("    {");
            sb.AppendLine("        public bool IsValidData()");
            sb.AppendLine("        {");
            sb.AppendLine("            return true;");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        public bool IsValidAfterLoad()");
            sb.AppendLine("        {");
            sb.AppendLine("            return true;");
            sb.AppendLine("        }");
            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        private string BuildInfoManager(TableSchema table)
        {
            var sb = new StringBuilder();
            AppendOnceHeader(sb);
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {table.Name} 테이블 로딩/보관");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public partial class {table.Name}InfoManager : InfoManagerBase<{table.KeyType}, {table.Name}Info>");
            sb.AppendLine("    {");
            sb.AppendLine($"        public override string TableName => \"{table.Name}\";");
            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        private string BuildInfoHandler(TableSchema table)
        {
            var sb = new StringBuilder();
            AppendOnceHeader(sb);
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    /// <summary>");
            sb.AppendLine($"    /// {table.Name} 데이터 조회 진입점");
            sb.AppendLine("    /// </summary>");
            sb.AppendLine($"    public static partial class {table.Name}InfoHandler");
            sb.AppendLine("    {");
            sb.AppendLine($"        public static {table.Name}Info GetData({table.KeyType} id)");
            sb.AppendLine("        {");
            sb.AppendLine($"            return DataManager.Instance.{table.Name}InfoManager.GetData(id);");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine($"        public static bool TryGetData({table.KeyType} id, out {table.Name}Info info)");
            sb.AppendLine("        {");
            sb.AppendLine($"            return DataManager.Instance.{table.Name}InfoManager.TryGetData(id, out info);");
            sb.AppendLine("        }");
            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        private string BuildDataManager(IReadOnlyList<string> tableNames)
        {
            var sb = new StringBuilder();
            AppendAutoGeneratedHeader(sb, "매번 재생성됩니다. 수정하지 마세요. 로딩 흐름은 Base/DataManager.cs 에 있습니다.");
            sb.AppendLine("using System.Collections.Generic;");
            sb.AppendLine();
            sb.AppendLine($"namespace {_param.@namespace}");
            sb.AppendLine("{");
            sb.AppendLine("    public partial class DataManager");
            sb.AppendLine("    {");
            sb.AppendLine("        // ============================================================");
            sb.AppendLine("        // Members");
            sb.AppendLine("        // ============================================================");
            foreach (var name in tableNames)
                sb.AppendLine($"        public {name}InfoManager {name}InfoManager {{ get; }} = new {name}InfoManager();");
            if (tableNames.Count > 0)
                sb.AppendLine();

            sb.AppendLine("        /// <summary>");
            sb.AppendLine("        /// 등록된 모든 InfoManager");
            sb.AppendLine("        /// </summary>");
            sb.AppendLine("        public IEnumerable<IInfoManager> InfoManagers");
            sb.AppendLine("        {");
            sb.AppendLine("            get");
            sb.AppendLine("            {");
            foreach (var name in tableNames)
                sb.AppendLine($"                yield return {name}InfoManager;");
            if (tableNames.Count == 0)
                sb.AppendLine("                yield break;");
            sb.AppendLine("            }");
            sb.AppendLine("        }");
            sb.AppendLine();

            sb.AppendLine("        // ============================================================");
            sb.AppendLine("        // Methods");
            sb.AppendLine("        // ============================================================");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>");
            sb.AppendLine("        /// 모든 테이블을 동기 로딩합니다.");
            sb.AppendLine("        /// </summary>");
            sb.AppendLine("        private bool LoadAll()");
            sb.AppendLine("        {");
            sb.AppendLine("            bool isSuccess = true;");
            foreach (var name in tableNames)
                sb.AppendLine($"            isSuccess &= {name}InfoManager.Load();");
            sb.AppendLine("            return isSuccess;");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>");
            sb.AppendLine("        /// 모든 테이블 로딩 후 테이블 간 검사를 진행합니다.");
            sb.AppendLine("        /// </summary>");
            sb.AppendLine("        private bool DoAfterLoad()");
            sb.AppendLine("        {");
            sb.AppendLine("            bool isSuccess = true;");
            foreach (var name in tableNames)
                sb.AppendLine($"            isSuccess &= {name}InfoManager.DoAfterLoad();");
            sb.AppendLine("            return isSuccess;");
            sb.AppendLine("        }");
            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        // ============================================================
        // Helpers
        // ============================================================

        private static void AppendAutoGeneratedHeader(StringBuilder sb, string note)
        {
            sb.AppendLine("// ============================================================");
            sb.AppendLine("// <auto-generated> TableAutomationTool");
            sb.AppendLine($"// {note}");
            sb.AppendLine("// ============================================================");
            sb.AppendLine();
        }

        private static void AppendOnceHeader(StringBuilder sb)
        {
            sb.AppendLine("// ============================================================");
            sb.AppendLine($"// Date : {DateTime.Now:yyyy-MM-dd}");
            sb.AppendLine("// TableAutomationTool 이 최초 1회 생성한 파일입니다. 이후 재생성되지 않으므로 자유롭게 수정합니다.");
            sb.AppendLine("// ============================================================");
            sb.AppendLine();
        }

        private static void WriteAlways(string path, string content)
        {
            File.WriteAllText(path, content, new UTF8Encoding(false));
            Logger.Instance.Log($"[CSharpInfoGenerator] Generated: {path}");
        }

        private static void WriteIfMissing(string path, string content)
        {
            if (File.Exists(path))
            {
                Logger.Instance.Log($"[CSharpInfoGenerator] Skip (already exists): {path}");
                return;
            }

            File.WriteAllText(path, content, new UTF8Encoding(false));
            Logger.Instance.Log($"[CSharpInfoGenerator] Generated (once): {path}");
        }

        private static bool TryReadTable(string binaryFilePath, out TableSchema table)
        {
            table = null!;

            if (!File.Exists(binaryFilePath))
            {
                Logger.Instance.Error($"[CSharpInfoGenerator] Binary file not found: {binaryFilePath}");
                return false;
            }

            var schema = BinarySchema.ReadFromBytes(File.ReadAllBytes(binaryFilePath));
            if (schema.ColumnCount == 0)
            {
                Logger.Instance.Error($"[CSharpInfoGenerator] Binary schema is empty: {binaryFilePath}");
                return false;
            }

            var columns = schema.Columns
                .Select(kvp => new ColumnSchema(kvp.Key, ConvertToCSharpType(kvp.Value), ToParameterName(kvp.Key)))
                .ToList();

            table = new TableSchema(Path.GetFileNameWithoutExtension(binaryFilePath), columns);
            return true;
        }

        private static string ToParameterName(string columnName)
        {
            var name = char.ToLowerInvariant(columnName[0]) + columnName.Substring(1);
            return CSharpKeywords.Contains(name) ? "@" + name : name;
        }

        /// <summary>
        /// Binary 타입 문자열을 C# 타입으로 변환한다. 매핑되지 않는 이름(UserEnum 등)은 그대로 쓴다.
        /// </summary>
        private static string ConvertToCSharpType(string typeString)
        {
            var normalizedType = typeString.Contains(',') ? typeString.Split(',')[0].Trim() : typeString;
            if (normalizedType.StartsWith("System."))
                normalizedType = normalizedType.Substring("System.".Length);

            if (normalizedType.EndsWith("[]"))
                return ConvertToCSharpType(normalizedType.Substring(0, normalizedType.Length - 2)) + "[]";

            return normalizedType switch
            {
                "Int16" or "short" => "short",
                "Int32" or "int" => "int",
                "Int64" or "long" => "long",
                "Single" or "float" => "float",
                "Double" or "double" => "double",
                "String" or "string" => "string",
                "Boolean" or "bool" => "bool",
                "DateTime" => "DateTime",
                _ => normalizedType
            };
        }

        private sealed record ColumnSchema(string Name, string Type, string ParameterName);

        private sealed record TableSchema(string Name, List<ColumnSchema> Columns)
        {
            public string KeyType => Columns[0].Type;
        }
    }
}
